boolean processNode(AstNode node) {
    if (validLines.contains(node.getLineno())) {
        // Don't add instrumentation if already there
        return true;
    }

    if (node.getParent() != null && node.getLineno() == node.getParent().getLineno()) {
        // Don't add instrumentation if it will be added by parent for the same line
        return true;
    }

    AstNode parent = node.getParent();
    if (parent instanceof ObjectProperty || parent instanceof FunctionCall) {
        return true;
    }

    if (node instanceof ContinueStatement) {
        if (node.getFirstChild() instanceof Name) {
            Name label = (Name) node.getFirstChild();
            addInstrumentationBefore(label.getNext());
        }
        return true;
    }

    if (node instanceof LabeledStatement) {
        LabeledStatement labeledStatement = (LabeledStatement) node;
        Statement statement = labeledStatement.getStatement();
        if (statement.getType() == Token.EMPTY) {
            Block block = new Block();
            block.addChildToBack(buildInstrumentationStatement(node.getLineno()));
            labeledStatement.setStatement(block);
        } else {
            addInstrumentationBefore(statement);
        }
        return true;
    }

    if (node instanceof Loop || node instanceof Loop || node instanceof VariableDeclaration || node instanceof LetNode) {
        addInstrumentationBefore(node);
        return true;
    }

    if (node instanceof SwitchCase) {
        SwitchCase switchCase = (SwitchCase) node;
        List<AstNode> statements = switchCase.getStatements();
        if (statements == null) {
            return true;
        }
        for (int i = statements.size() - 1; i >= 0; i--) {
            statements.add(i, buildInstrumentationStatement(switchCase.getLineno()));
        }
        return true;
    }

    if (node instanceof FunctionNode || node instanceof TryStatement || isDebugStatement(node) || node instanceof ReturnStatement || node instanceof IfStatement) {
        addInstrumentationBefore(node);
    }

    return true;
}

